from pysat.solvers import Glucose3

n = 20

def var(i, j):
    if i > j:
        i, j = j, i
    return i * n + j + 1

solver = Glucose3()

for i in range(n):
    for j in range(i + 1, n):
        for k in range(j + 1, n):
            solver.add_clause([-var(i, j), -var(j, k), -var(i, k)])

aux_var = n * n + 1

for i in range(n):
    for j in range(i + 1, n):
        clause = [var(i, j)]
        for k in range(n):
            if k == i or k == j:
                continue
            c = aux_var
            aux_var += 1
            solver.add_clause([-c, var(i, k)])
            solver.add_clause([-c, var(j, k)])
            solver.add_clause([-var(i, k), -var(j, k), c])
            clause.append(c)
        solver.add_clause(clause)

fixed = [(1,18), (4,18), (16,18), (4,19), (17,18), (11,19), (3,19)]
for u, v in fixed:
    solver.add_clause([var(u, v)])

if solver.solve():
    model = solver.get_model()
    edges = []
    for i in range(n):
        for j in range(i + 1, n):
            if model[var(i, j) - 1] > 0:
                edges.extend([i, j])
    print("SAT")
    print(edges)
else:
    print("UNSAT")
